#!/usr/bin/env python3
"""patch_remove_landmark_and_dup_check.py — Suppression securisee + anti-doublon.

1) CREE tools/refine/remove_landmark.py — LE chemin canonique pour supprimer
   un LM (gtamapdata n'a pas d'API de deletion). Gardes: refuse si markings
   vivants, si reference comme source, ou si present dans un mesh; --force
   documente pour les exceptions. Purge aussi les residus pixels.
2) PATCHE tools/audit/invariants.py — nouveau check FAIL: doublons
   case-insensitive (landmarks ET cameras). Valide en sandbox: FAIL sur
   'hotel Victor (SE)'/'Hotel Victor (SE)' avant fix, OK apres, garde testee
   sur un LM vivant (REFUSE).

Apres --apply, le fix de donnees se fait par L'OUTIL (pas ce patch):
    python3 tools/refine/remove_landmark.py "hotel Victor (SE)"          # dry-run
    python3 tools/refine/remove_landmark.py "hotel Victor (SE)" --apply
Contexte: minuscule = residu de triangulation ratee (err 32.99m vs 0.10m,
82m du bon point, zero marking, zero reference).

Idempotent, sha-garde sur invariants.py (HEAD 68c7889), dry-run par defaut.
"""
import hashlib, json, os, shutil, sys

PROJ = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
APPLY = "--apply" in sys.argv
PAYLOAD = json.loads("{\"tools/refine/remove_landmark.py\": {\"sha_head\": null, \"content\": \"#!/usr/bin/env python3\\n\\\"\\\"\\\"remove_landmark.py \\u2014 Suppression SECURISEE d'un landmark.\\n\\ngtamapdata n'a pas d'API de suppression (update_landmark ne couvre pas les\\ndeletions de cle); cet outil est LE chemin canonique, avec gardes:\\n  - REFUSE si le LM a des markings vivants dans pixels.json\\n  - REFUSE si le LM est reference comme source_camera d'un autre LM (cas (geometric:))\\n  - REFUSE si le LM est reference dans un mesh procedural (tools/meshes/*.py)\\nBypass des gardes: --force (toujours expliquer pourquoi dans le commit).\\n\\nPremier usage: 'hotel Victor (SE)' (minuscule) \\u2014 doublon case-insensitive de\\n'Hotel Victor (SE)', erreur 32.99m vs 0.10m, 82m du bon point, zero marking,\\nzero reference. Residu d'une vieille triangulation ratee.\\n\\nUsage:\\n    python3 tools/refine/remove_landmark.py \\\"Nom Du LM\\\"           # dry-run\\n    python3 tools/refine/remove_landmark.py \\\"Nom Du LM\\\" --apply\\n\\\"\\\"\\\"\\nimport argparse, glob, json, os, shutil, sys\\n\\nROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\\nsys.path.insert(0, ROOT)\\nsys.path.insert(0, os.path.join(ROOT, \\\"tools\\\"))\\nimport gtamapdata as md\\nfrom common import save_json\\n\\n\\ndef main():\\n    ap = argparse.ArgumentParser()\\n    ap.add_argument(\\\"name\\\")\\n    ap.add_argument(\\\"--apply\\\", action=\\\"store_true\\\")\\n    ap.add_argument(\\\"--force\\\", action=\\\"store_true\\\")\\n    args = ap.parse_args()\\n    name = args.name\\n\\n    if name not in md.landmarks:\\n        sys.exit(f\\\"ERROR: LM {name!r} introuvable\\\")\\n\\n    blocks = []\\n    observers = [c for c, obs in md.pixels.items() if obs.get(name) is not None]\\n    if observers:\\n        blocks.append(f\\\"markings vivants dans {len(observers)} cam(s): {observers[:4]}\\\")\\n    refs = [n for n, m in md.landmarks_meta.items()\\n            if name in ((m or {}).get(\\\"source_cameras\\\") or []) and n != name]\\n    if refs:\\n        blocks.append(f\\\"reference comme source par {len(refs)} LM(s): {refs[:4]}\\\")\\n    mesh_refs = []\\n    for f in glob.glob(os.path.join(ROOT, \\\"tools\\\", \\\"meshes\\\", \\\"*.py\\\")):\\n        if name in open(f).read():\\n            mesh_refs.append(os.path.basename(f))\\n    if mesh_refs:\\n        blocks.append(f\\\"reference dans mesh(es): {mesh_refs}\\\")\\n\\n    meta = md.landmarks_meta.get(name) or {}\\n    xyz = md.landmarks.get(name)\\n    print(f\\\"LM: {name!r}\\\")\\n    print(f\\\"  xyz={[round(v, 2) for v in xyz] if xyz is not None else None} \\\"\\n          f\\\"err={meta.get('error_m')} srcs={meta.get('source_cameras')}\\\")\\n    if blocks:\\n        for b in blocks:\\n            print(\\\"  GARDE:\\\", b)\\n        if not args.force:\\n            sys.exit(\\\"REFUSE (utilise --force si c'est vraiment voulu)\\\")\\n        print(\\\"  --force: gardes ignorees\\\")\\n    else:\\n        print(\\\"  aucune reference vivante \\u2014 suppression sure\\\")\\n\\n    if not args.apply:\\n        print(\\\"DRY-RUN. Relance avec --apply pour ecrire.\\\")\\n        return\\n\\n    lm_path = os.path.join(ROOT, \\\"gtamapdata\\\", \\\"landmarks.json\\\")\\n    shutil.copy(lm_path, lm_path + \\\".bak_remove\\\")\\n    with open(lm_path) as f:\\n        data = json.load(f)\\n    del data[name]\\n    save_json(lm_path, data)\\n    # purge aussi les markings null residuels dans pixels.json le cas echeant\\n    px_path = os.path.join(ROOT, \\\"gtamapdata\\\", \\\"pixels.json\\\")\\n    with open(px_path) as f:\\n        px = json.load(f)\\n    touched = False\\n    for c in list(px):\\n        if name in px[c]:\\n            del px[c][name]\\n            touched = True\\n    if touched:\\n        shutil.copy(px_path, px_path + \\\".bak_remove\\\")\\n        save_json(px_path, px)\\n    print(f\\\"APPLIED: {name!r} supprime (backup landmarks.json.bak_remove\\\"\\n          + (\\\", pixels.json.bak_remove\\\" if touched else \\\"\\\") + \\\")\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"}, \"tools/audit/invariants.py\": {\"sha_head\": \"27be364cc19b\", \"content\": \"#!/usr/bin/env python3\\n\\\"\\\"\\\"invariants.py \\u2014 Garde-fou pre-commit pour gtamapdata/. Exit 1 si violation.\\n\\nNe le contourne JAMAIS: chaque famille de bug d'aujourd'hui (2026-06-10) aurait\\nete pognee ici \\u2014 poses fantomes (ecrit != simule), violations z ecrites en\\nbypassant update_landmark, leaks bougees par un solve trop confiant.\\n\\nCHECKS:\\n  1. Z-CONSTRAINTS: tout LM avec z_constraint fixed a xyz[2] == value sur\\n     disque (doctrine \\\"single source of truth\\\", retablie session du soir).\\n  2. LEAKS IMMOBILES: toute cam HUD-locked (is_triangulation_trusted) a une\\n     pose identique a la reference gelee tools/audit/leak_poses_ref.json.\\n     Apres un intake T3 legitime qui AJOUTE des leaks: --freeze pour regeler.\\n     Une leak qui BOUGE n'est jamais legitime.\\n  3. SCHEMA: cameras (xyz3/ypr3/fov2/size2), landmarks (xyz None|3),\\n     pixels -> cams existantes, source_cameras -> cams existantes.\\n\\nUsage:\\n    python3 tools/audit/invariants.py            # check, exit 1 si echec\\n    python3 tools/audit/invariants.py --freeze   # (re)gele la reference leaks\\nConvention: rouler AVANT chaque `git commit` qui touche gtamapdata/.\\n\\\"\\\"\\\"\\nimport argparse, json, os, sys\\n\\nROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\\nsys.path.insert(0, ROOT)\\nimport gtamapdata as md\\nsys.path.insert(0, os.path.join(ROOT, \\\"tools\\\"))\\nfrom leak_cam_audit import is_triangulation_trusted\\n\\nREF_PATH = os.path.join(ROOT, \\\"tools\\\", \\\"audit\\\", \\\"leak_poses_ref.json\\\")\\nEPS = 1e-6\\n\\n\\ndef locked_cams():\\n    return sorted(n for n in md.cameras if is_triangulation_trusted(n, cameras=md.cameras))\\n\\n\\ndef main():\\n    ap = argparse.ArgumentParser()\\n    ap.add_argument(\\\"--freeze\\\", action=\\\"store_true\\\",\\n                    help=\\\"(re)gele la reference des poses leaks depuis l'etat actuel\\\")\\n    ap.add_argument(\\\"--strict\\\", action=\\\"store_true\\\",\\n                    help=\\\"les WARN (dette legacy, ex: provenance orpheline) deviennent des FAIL\\\")\\n    args = ap.parse_args()\\n\\n    if args.freeze:\\n        ref = {n: {\\\"xyz\\\": md.cameras[n][\\\"xyz\\\"], \\\"ypr\\\": md.cameras[n][\\\"ypr\\\"],\\n                   \\\"fov\\\": md.cameras[n][\\\"fov\\\"]} for n in locked_cams()}\\n        with open(REF_PATH, \\\"w\\\") as f:\\n            json.dump(ref, f, indent=1, sort_keys=True)\\n        print(f\\\"FROZEN: {len(ref)} poses leaks -> {REF_PATH} (a committer)\\\")\\n        return 0\\n\\n    fails = []\\n    warns = []\\n\\n    def is_provenance_marker(s_):\\n        # \\\"(geometric: ...)\\\" et les marqueurs TOUT_EN_MAJUSCULES (ex:\\n        # CONSTRUCTED_FINAL_FIT du rebuild Portofino) ne sont pas des cams.\\n        return s_.startswith(\\\"(\\\") or (s_.replace(\\\"_\\\", \\\"\\\").isupper() and \\\"_\\\" in s_)\\n\\n    # \\u2500\\u2500 1. z_constraints coherentes sur disque \\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\n    for n, m in md.landmarks_meta.items():\\n        zc = (m or {}).get(\\\"z_constraint\\\")\\n        if zc and zc.get(\\\"type\\\") == \\\"fixed\\\" and md.landmarks.get(n) is not None:\\n            if abs(md.landmarks[n][2] - float(zc[\\\"value\\\"])) > EPS:\\n                fails.append(f\\\"Z-CONSTRAINT: {n} z={md.landmarks[n][2]:+.3f} != {zc['value']}\\\")\\n\\n    # \\u2500\\u2500 2. leaks immobiles vs reference gelee \\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\n    if not os.path.exists(REF_PATH):\\n        fails.append(f\\\"LEAK-REF: {REF_PATH} absent \\u2014 roule --freeze une premiere fois\\\")\\n    else:\\n        with open(REF_PATH) as f:\\n            ref = json.load(f)\\n        cur = set(locked_cams())\\n        for n, r in ref.items():\\n            if n not in md.cameras:\\n                fails.append(f\\\"LEAK: {n} dans la ref mais absente de cameras.json\\\")\\n                continue\\n            c = md.cameras[n]\\n            for k in (\\\"xyz\\\", \\\"ypr\\\", \\\"fov\\\"):\\n                a, b = c.get(k), r.get(k)\\n                if a is None or b is None:\\n                    if a != b:\\n                        fails.append(f\\\"LEAK: {n}.{k} {b} -> {a}\\\")\\n                    continue\\n                if any((x is None) != (y is None) or\\n                       (x is not None and abs(float(x) - float(y)) > EPS)\\n                       for x, y in zip(a, b)):\\n                    fails.append(f\\\"LEAK: {n}.{k} a bouge: {b} -> {a}\\\")\\n        new_leaks = cur - set(ref)\\n        if new_leaks:\\n            print(f\\\"NOTE: {len(new_leaks)} nouvelles cams HUD-locked pas dans la ref \\\"\\n                  f\\\"(normal apres intake; --freeze pour les geler): {sorted(new_leaks)[:5]}...\\\")\\n\\n    # \\u2500\\u2500 2b. doublons case-insensitive (LMs et cams) \\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\n    import collections as _coll\\n    for label, keys in ((\\\"landmarks\\\", md.landmarks), (\\\"cameras\\\", md.cameras)):\\n        low = _coll.Counter(k.lower() for k in keys)\\n        for k, v in low.items():\\n            if v > 1:\\n                originals = [o for o in keys if o.lower() == k]\\n                fails.append(f\\\"DOUBLON {label}: {originals} ne different que par la casse\\\")\\n\\n    # \\u2500\\u2500 3. schema \\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\n    for n, c in md.cameras.items():\\n        for k, ln in ((\\\"xyz\\\", 3), (\\\"ypr\\\", 3), (\\\"fov\\\", 2), (\\\"size\\\", 2)):\\n            v = c.get(k)\\n            if not isinstance(v, (list, tuple)) or len(v) != ln:\\n                fails.append(f\\\"SCHEMA cam {n}.{k}: {v!r}\\\")\\n    for n in md.landmarks:\\n        v = md.landmarks[n]\\n        if v is not None and (not hasattr(v, \\\"__len__\\\") or len(v) != 3):\\n            fails.append(f\\\"SCHEMA lm {n}.xyz: {v!r}\\\")\\n        srcs = (md.landmarks_meta.get(n) or {}).get(\\\"source_cameras\\\") or []\\n        for s in srcs:\\n            if not is_provenance_marker(s) and s not in md.cameras:\\n                warns.append(f\\\"PROVENANCE lm {n}: source_camera orpheline '{s}' \\\"\\n                             \\\"(rename/suppression historique \\u2014 la protection FIXED \\\"\\n                             \\\"ne s'applique plus a cette source)\\\")\\n    for cn in md.pixels:\\n        if cn not in md.cameras:\\n            warns.append(f\\\"PROVENANCE pixels: cam orpheline '{cn}' \\\"\\n                         f\\\"({len(md.pixels[cn])} markings morts \\u2014 TODO: remap vers la \\\"\\n                         \\\"cam renommee ou purger)\\\")\\n\\n    if warns:\\n        print(f\\\"WARNINGS: {len(warns)} (dette legacy, --strict pour en faire des FAIL)\\\")\\n        for w in warns[:8]:\\n            print(\\\"  WARN\\\", w)\\n        if len(warns) > 8:\\n            print(f\\\"  ... +{len(warns)-8}\\\")\\n        if args.strict:\\n            fails.extend(warns)\\n\\n    n_zc = sum(1 for m in md.landmarks_meta.values() if (m or {}).get(\\\"z_constraint\\\"))\\n    if fails:\\n        print(f\\\"INVARIANTS: {len(fails)} VIOLATION(S)\\\")\\n        for f_ in fails[:30]:\\n            print(\\\"  FAIL\\\", f_)\\n        if len(fails) > 30:\\n            print(f\\\"  ... +{len(fails)-30}\\\")\\n        return 1\\n    print(f\\\"INVARIANTS OK \\u2014 z_constraints={n_zc}, leaks_ref={len(json.load(open(REF_PATH))) if os.path.exists(REF_PATH) else 0}, \\\"\\n          f\\\"cams={len(md.cameras)}, lms={len(md.landmarks)}\\\")\\n    return 0\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    sys.exit(main())\\n\"}}")

todo = []
for rel, item in PAYLOAD.items():
    path = os.path.join(PROJ, rel)
    if not os.path.exists(path):
        todo.append(("create", rel, item["content"]))
        continue
    cur = open(path).read()
    if cur == item["content"]:
        print(f"SKIP {rel}: deja a jour")
        continue
    if "DOUBLON" in cur:
        print(f"SKIP {rel}: deja patche (version differente — verifier)")
        continue
    if item["sha_head"] and hashlib.sha256(cur.encode()).hexdigest()[:12] != item["sha_head"]:
        sys.exit(f"ERROR {rel}: a derive du HEAD 68c7889 attendu — abort")
    todo.append(("patch", rel, item["content"]))

if not todo:
    sys.exit(0)
for action, rel, _ in todo:
    print(("APPLY " if APPLY else "WOULD APPLY ") + action + " " + rel)
if not APPLY:
    print("DRY-RUN: rien ecrit. Relance avec --apply.")
    sys.exit(0)
for action, rel, content in todo:
    path = os.path.join(PROJ, rel)
    if action == "patch":
        shutil.copy(path, path + ".bak_dup")
    open(path, "w").write(content)
print("DONE. Next: python3 tools/refine/remove_landmark.py \"hotel Victor (SE)\" --apply && python3 tools/audit/invariants.py")
